# Explicit spec table + lazy-loading dispatcher
import importlib
from dataclasses import dataclass
from functools import cache
from types import MappingProxyType
from typing import Protocol, Any

class Processor(Protocol):
    def __call__(self, df: Any, org_id: int) -> int: ...

@dataclass(frozen=True, slots=True)
class ModuleSpec:
    key: str        # report type
    module: str     # dotted module path, imported lazily
    func: str       # attribute name of the processor

_MODULE_SPECS: tuple[ModuleSpec, ...] = (
    ModuleSpec("amazon_orders", "processors.amazon", "process_orders"),
    ModuleSpec("amazon_inventory", "processors.amazon", "process_inventory"),
    ModuleSpec("flipkart_orders", "processors.flipkart", "process_orders"),
)

def _build(specs):
    table = {}
    for s in specs:
        if s.key in table:
            raise ValueError(f"duplicate report type: {s.key}")
        table[s.key] = s
    return MappingProxyType(table)              # read-only view

MODULE_DISPATCH = _build(_MODULE_SPECS)

class UnsupportedReportType(Exception): ...

@cache
def get_processor(report_type: str) -> Processor:
    try:
        spec = MODULE_DISPATCH[report_type]
    except KeyError:
        raise UnsupportedReportType(
            f"{report_type!r} not supported; valid: {sorted(MODULE_DISPATCH)}") from None
    module = importlib.import_module(spec.module)   # import happens on first use only
    return getattr(module, spec.func)

def dispatch(report_type: str, df, org_id: int) -> int:
    return get_processor(report_type)(df, org_id)
