# Decorator-based registry (eager, self-registering handlers)
from collections.abc import Callable

WEBHOOK_HANDLERS: dict[str, Callable[[dict], None]] = {}

def on_event(event_type: str):
    def deco(fn):
        if event_type in WEBHOOK_HANDLERS:
            raise ValueError(f"duplicate handler for {event_type}")
        WEBHOOK_HANDLERS[event_type] = fn
        return fn
    return deco

@on_event("payment.captured")
def handle_captured(payload: dict) -> None:
    print("captured", payload["id"])

@on_event("payment.failed")
def handle_failed(payload: dict) -> None:
    print("failed", payload["id"])

def handle_webhook(body: dict) -> None:
    handler = WEBHOOK_HANDLERS.get(body["event"])
    if handler is None:
        return                       # ignore unknown events (log in real code)
    handler(body["payload"])

handle_webhook({"event": "payment.captured", "payload": {"id": "pay_1"}})
