# Type-based dispatch with functools.singledispatch
from functools import singledispatch
from pathlib import Path

@singledispatch
def load(source) -> bytes:
    raise TypeError(f"unsupported source: {type(source).__name__}")

@load.register
def _(source: Path) -> bytes:
    return source.read_bytes()

@load.register
def _(source: str) -> bytes:          # treat strings as URLs
    import requests
    return requests.get(source, timeout=30).content
